/**
 * 角色系统聊天扫描引擎
 *
 * 负责从聊天消息中解析 <Character> 和 <Skill> 标签中的 CMD 指令，
 * 并将解析结果 dispatch 回 store，由 store 统一更新状态。
 *
 * 核心原则：
 * - 本模块只负责"解析"，不负责"存储"
 * - 所有 mutation 统一通过 store.scanDispatch() 进行
 * - 检查点由 store 的 watchEffect 自动持久化
 */

import { klona } from 'klona';
import type {
  角色,
  角色检查点,
} from '../types/role';
import {
  角色Schema,
  技能Schema,
  预定义角色字段列表,
} from '../types/role';
import { nextRoleId, nextSkillId } from './roleIdGenerator';
import {
  isValidDomainKey,
  随机分配效果值,
  checkSingleModLimit,
} from './skillEffectWhitelist';
import { useVNStore } from '../store';

// ============================================================================
// 防抖定时器
// ============================================================================

let debounceTimer: ReturnType<typeof setTimeout> | null = null;

const CONFIG = {
  debounceDelay: 800,
  checkpointInterval: 25,
};

// ============================================================================
// 检查点（由 store 的 watchEffect 持久化，此处仅运行时使用）
// ============================================================================

let _checkpoint: 角色检查点 | null = null;

function loadCheckpoint(): 角色检查点 | null {
  if (_checkpoint) return _checkpoint;
  const vars = getVariables({ type: 'chat' });
  const cp = vars?.role_checkpoint as 角色检查点 | null;
  if (!cp || cp.message_id == null) return null;
  _checkpoint = cp;
  return _checkpoint;
}

function saveCheckpoint(messageId: number, maxId: number): void {
  const vars = getVariables({ type: 'chat' });
  const dbMap = (vars?.role_db_map as Record<string, 角色>) || {};
  _checkpoint = {
    message_id: messageId,
    max_id: maxId,
    db_map: klona(dbMap),
  };
  insertOrAssignVariables(klona({ role_checkpoint: _checkpoint }), { type: 'chat' });
}

function invalidateCheckpoint(): void {
  _checkpoint = null;
  insertOrAssignVariables(klona({ role_checkpoint: null }), { type: 'chat' });
}

function shouldSaveCheckpoint(): boolean {
  const cp = loadCheckpoint();
  if (!cp || cp.message_id == null) return true;
  const allMessages = getChatMessages('all');
  const latestId = allMessages[allMessages.length - 1]?.message_id ?? 0;
  return (latestId - cp.message_id) >= CONFIG.checkpointInterval;
}

// ============================================================================
// 正则表达式
// ============================================================================

const REGEX_CHAR_BLOCK = /<Character>\s*([\s\S]*?)\s*<\/Character>/gi;
const REGEX_CHAR_ADD = /CMD:ADD\s*[|｜]\s*([\s\S]*?)(?=\s*CMD:|$)/gi;
const REGEX_CHAR_MOD = /CMD:MOD\s*[|｜]\s*([^\|｜]+?)\s*[|｜]\s*([\s\S]*?)(?=\s*CMD:|$)/gi;
const REGEX_CHAR_DEL = /CMD:DEL\s*[|｜]\s*([^\|｜]+?)(?=\s*[|｜]?\s*CMD:|$)/gi;
const REGEX_CHAR_EQUIP = /CMD:EQUIP\s*[|｜]\s*([^\|｜]+?)\s*[|｜]\s*([^\|｜]+?)(?=\s*[|｜]?\s*CMD:|$)/gi;
const REGEX_CHAR_UNEQUIP = /CMD:UNEQUIP\s*[|｜]\s*([^\|｜]+?)\s*[|｜]\s*([^\|｜]+?)(?=\s*[|｜]?\s*CMD:|$)/gi;
const REGEX_SKILL_BLOCK = /<Skill>\s*([\s\S]*?)\s*<\/Skill>/gi;
const REGEX_SKILL_ADD = /CMD:ADD\s*[|｜]\s*([^\|｜]+?)\s*[|｜]\s*([^\|｜]+?)\s*[|｜]\s*([^\|｜]+?)(?:\s*[|｜]\s*(.+))?/gi;
const REGEX_SKILL_DEL = /CMD:DEL_SKILL\s*[|｜]\s*([^\|｜]+?)(?=\s*[|｜]?\s*CMD:|$)/gi;

// ============================================================================
// 工具函数
// ============================================================================

function parseKeyValuePairs(cmdPart: string): Record<string, string> {
  const fields: Record<string, string> = {};
  const parts = cmdPart.split(/[|｜]/);
  for (const part of parts) {
    const colonMatch = part.match(/^(.+?)[:：]\s*([\s\S]*)$/);
    if (colonMatch) {
      const key = colonMatch[1].trim();
      const value = colonMatch[2].trim();
      if (key) fields[key] = value;
    }
  }
  return fields;
}

function parseAttributeField(value: string): Record<string, number> {
  const defaults: Record<string, number> = {
    战力: 0, 技巧: 0, 智慧: 0, 社交: 0, 谨慎: 0, 运气: 0,
  };
  if (!value) return { ...defaults };
  const attrParts = value.split(/[/]/);
  for (const part of attrParts) {
    const [key, val] = part.split(':');
    if (key && val !== undefined) {
      const trimmedKey = key.trim();
      const numVal = parseInt(val.trim(), 10);
      if (!isNaN(numVal) && trimmedKey in defaults) {
        defaults[trimmedKey] = Math.min(5, Math.max(0, numVal));
      }
    }
  }
  return defaults;
}

function isPredefinedField(key: string): boolean {
  return (预定义角色字段列表 as readonly string[]).includes(key);
}

// ============================================================================
// 扫描单条消息
// ============================================================================

function scanMessage(msg: any, store: ReturnType<typeof useVNStore>): void {
  if (!msg || !msg.content) return;

  const content: string = msg.content;

  // ---- 扫描 Character 块 ----
  let charMatch: RegExpExecArray | null;
  REGEX_CHAR_BLOCK.lastIndex = 0;
  while ((charMatch = REGEX_CHAR_BLOCK.exec(content)) !== null) {
    const blockContent = charMatch[1];

    // CMD:ADD
    let addMatch: RegExpExecArray | null;
    REGEX_CHAR_ADD.lastIndex = 0;
    while ((addMatch = REGEX_CHAR_ADD.exec(blockContent)) !== null) {
      handleCharAdd(addMatch[1].trim(), store);
    }

    // CMD:MOD
    let modMatch: RegExpExecArray | null;
    REGEX_CHAR_MOD.lastIndex = 0;
    while ((modMatch = REGEX_CHAR_MOD.exec(blockContent)) !== null) {
      const name = modMatch[1].trim();
      const cmdPart = modMatch[2].trim();
      handleCharMod(name, cmdPart, store);
    }

    // CMD:DEL
    let delMatch: RegExpExecArray | null;
    REGEX_CHAR_DEL.lastIndex = 0;
    while ((delMatch = REGEX_CHAR_DEL.exec(blockContent)) !== null) {
      const name = delMatch[1].trim();
      handleCharDel(name, store);
    }

    // CMD:EQUIP
    let equipMatch: RegExpExecArray | null;
    REGEX_CHAR_EQUIP.lastIndex = 0;
    while ((equipMatch = REGEX_CHAR_EQUIP.exec(blockContent)) !== null) {
      const name = equipMatch[1].trim();
      const skillName = equipMatch[2].trim();
      handleCharEquip(name, skillName, store);
    }

    // CMD:UNEQUIP
    let unequipMatch: RegExpExecArray | null;
    REGEX_CHAR_UNEQUIP.lastIndex = 0;
    while ((unequipMatch = REGEX_CHAR_UNEQUIP.exec(blockContent)) !== null) {
      const name = unequipMatch[1].trim();
      const skillName = unequipMatch[2].trim();
      handleCharUnequip(name, skillName, store);
    }
  }

  // ---- 扫描 Skill 块 ----
  let skillMatch: RegExpExecArray | null;
  REGEX_SKILL_BLOCK.lastIndex = 0;
  while ((skillMatch = REGEX_SKILL_BLOCK.exec(content)) !== null) {
    const blockContent = skillMatch[1];

    let addMatch: RegExpExecArray | null;
    REGEX_SKILL_ADD.lastIndex = 0;
    while ((addMatch = REGEX_SKILL_ADD.exec(blockContent)) !== null) {
      const cmdPart = [
        addMatch[1].trim(),
        addMatch[2].trim(),
        addMatch[3].trim(),
        addMatch[4]?.trim() || '',
      ].join('|');
      handleSkillAdd(cmdPart, store);
    }

    let delMatch: RegExpExecArray | null;
    REGEX_SKILL_DEL.lastIndex = 0;
    while ((delMatch = REGEX_SKILL_DEL.exec(blockContent)) !== null) {
      const name = delMatch[1].trim();
      handleSkillDel(name, store);
    }
  }
}

// ============================================================================
// CMD 处理器（调用 store.scanDispatch）
// ============================================================================

function handleCharAdd(cmdPart: string, store: ReturnType<typeof useVNStore>): void {
  try {
    const fields = parseKeyValuePairs(cmdPart);
    if (!fields['姓名']) { console.warn('[roleScanner] CMD:ADD 缺少必填字段: 姓名'); return; }
    if (!fields['属性']) { console.warn('[roleScanner] CMD:ADD 缺少必填字段: 属性'); return; }

    const name = fields['姓名'];

    // 检查同名角色
    const existing = store.getRoleByName(name);
    if (existing) { console.info(`[roleScanner] 跳过已存在的角色: ${name}`); return; }

    const id = nextRoleId();
    const 属性 = parseAttributeField(fields['属性']);

    const rawRole: Record<string, unknown> = {
      id,
      姓名: name,
      属性,
      已装备技能: [],
      状态: '空闲',
      当前任务: null,
      记录: [],
    };

    const predefinedFields = [
      '外貌', '性格', '出身', '定位', '说话风格', '喜好', '特长', '职业', '背景故事',
    ];
    for (const field of predefinedFields) {
      if (fields[field]) rawRole[field] = fields[field];
    }
    for (const [key, value] of Object.entries(fields)) {
      if (!isPredefinedField(key) && key !== 'id') rawRole[key] = value;
    }

    const role = 角色Schema.parse(rawRole);
    console.info(`[roleScanner] 解析角色: ${role.姓名} (${role.id})`);
    store.scanDispatch({ type: 'ADD_ROLE', role });
  } catch (e) {
    console.error('[roleScanner] CMD:ADD 解析失败:', e);
  }
}

function handleCharMod(
  name: string,
  cmdPart: string,
  store: ReturnType<typeof useVNStore>,
): void {
  const existing = store.getRoleByName(name);
  if (!existing) { console.warn(`[roleScanner] CMD:MOD 目标角色不存在: ${name}`); return; }

  try {
    const fields = parseKeyValuePairs(cmdPart);
    const updates: Partial<角色> = {};

    for (const [key, value] of Object.entries(fields)) {
      if (key === '属性') {
        updates.属性 = parseAttributeField(value) as 角色['属性'];
      } else {
        (updates as Record<string, unknown>)[key] = value;
      }
    }

    store.scanDispatch({ type: 'MOD_ROLE', id: existing.id, updates });
    console.info(`[roleScanner] 修改角色: ${name}`);
  } catch (e) {
    console.error('[roleScanner] CMD:MOD 解析失败:', e);
  }
}

function handleCharDel(name: string, store: ReturnType<typeof useVNStore>): void {
  const existing = store.getRoleByName(name);
  if (!existing) { console.warn(`[roleScanner] CMD:DEL 目标角色不存在: ${name}`); return; }
  store.scanDispatch({ type: 'DEL_ROLE', id: existing.id });
  console.info(`[roleScanner] 删除角色: ${name}`);
}

function handleCharEquip(
  name: string,
  skillName: string,
  store: ReturnType<typeof useVNStore>,
): void {
  const existing = store.getRoleByName(name);
  if (!existing) { console.warn(`[roleScanner] CMD:EQUIP 目标角色不存在: ${name}`); return; }

  const skill = store.getSkillByName(skillName);
  if (!skill) { console.warn(`[roleScanner] CMD:EQUIP 技能不存在: ${skillName}`); return; }

  store.scanDispatch({ type: 'EQUIP_SKILL', roleId: existing.id, skillId: skill.id });
  console.info(`[roleScanner] 角色 ${name} 装备技能: ${skillName}`);
}

function handleCharUnequip(
  name: string,
  skillName: string,
  store: ReturnType<typeof useVNStore>,
): void {
  const existing = store.getRoleByName(name);
  if (!existing) { console.warn(`[roleScanner] CMD:UNEQUIP 目标角色不存在: ${name}`); return; }
  const skill = store.getSkillByName(skillName);
  if (!skill) { console.warn(`[roleScanner] CMD:UNEQUIP 技能不存在: ${skillName}`); return; }
  store.scanDispatch({ type: 'UNEQUIP_SKILL', roleId: existing.id, skillId: skill.id });
  console.info(`[roleScanner] 角色 ${name} 卸下技能: ${skillName}`);
}

function handleSkillAdd(cmdPart: string, store: ReturnType<typeof useVNStore>): void {
  try {
    const parts = cmdPart.split(/[|｜]/).map(s => s.trim());
    if (parts.length < 3) { console.warn('[roleScanner] CMD:ADD 技能格式错误，需要至少 名称|emoji|描述'); return; }

    const [名称, emoji, 描述, ...rest] = parts;
    const extraPart = rest.join('|');

    if (!名称) { console.warn('[roleScanner] CMD:ADD 缺少技能名称'); return; }

    // 检查同名技能
    const existing = store.getSkillByName(名称);
    if (existing) { console.info(`[roleScanner] 跳过已存在的技能: ${名称}`); return; }

    const id = nextSkillId();
    const 效果: Array<{ 域: string; 键: string; 值: number }> = [];

    if (extraPart) {
      if (!checkSingleModLimit(extraPart)) {
        console.warn(`[roleScanner] 技能 ${名称} 包含多个 mod:，违反单 mod 限制`);
        return;
      }
      const modMatch = extraPart.match(/mod:\s*([^\s,，]+)\.([^\s,，]+)/);
      if (modMatch) {
        const 域 = modMatch[1];
        const 键 = modMatch[2];
        if (!isValidDomainKey(域, 键)) {
          console.warn(`[roleScanner] 技能 ${名称} 的 mod: ${域}.${键} 不在白名单中`);
          return;
        }
        const 值 = 随机分配效果值(域, 键);
        if (值 !== null) 效果.push({ 域, 键, 值 });
      }
    }

    const skill = 技能Schema.parse({
      id,
      名称,
      emoji: emoji || '',
      描述: 描述 || '',
      效果,
    });

    console.info(`[roleScanner] 解析技能: ${skill.名称} (${skill.id})`);
    store.scanDispatch({ type: 'ADD_SKILL', skill });
  } catch (e) {
    console.error('[roleScanner] CMD:ADD 技能解析失败:', e);
  }
}

function handleSkillDel(name: string, store: ReturnType<typeof useVNStore>): void {
  const skill = store.getSkillByName(name);
  if (!skill) { console.warn(`[roleScanner] CMD:DEL_SKILL 目标技能不存在: ${name}`); return; }
  store.scanDispatch({ type: 'DEL_SKILL', id: skill.id });
  console.info(`[roleScanner] 删除技能: ${name}`);
}

// ============================================================================
// 扫描执行
// ============================================================================

/**
 * 执行扫描
 * @param mode - 'full': 全量扫描 | 'incremental': 增量扫描
 */
export function performScan(mode: 'full' | 'incremental'): void {
  const store = useVNStore();
  const allMessages = getChatMessages('all');
  let scanFromIndex = 0;

  if (mode === 'incremental') {
    const cp = loadCheckpoint();
    if (cp && cp.message_id != null) {
      scanFromIndex = allMessages.findIndex(m => m.message_id > cp.message_id);
      if (scanFromIndex === -1) {
        console.info('[roleScanner] 无新消息，跳过扫描');
        return;
      }
      console.info(`[roleScanner] 增量扫描: 从索引 ${scanFromIndex} 开始（检查点: ${cp.message_id}）`);
    } else {
      mode = 'full';
      scanFromIndex = 0;
      console.info('[roleScanner] 无检查点，退化为全量扫描');
    }
  }

  if (mode === 'full') {
    scanFromIndex = 0;
    console.info(`[roleScanner] 全量扫描: 共 ${allMessages.length} 条消息`);
  }

  const messagesToScan = allMessages.slice(scanFromIndex);
  for (const msg of messagesToScan) {
    scanMessage(msg, store);
  }

  if (shouldSaveCheckpoint()) {
    const latestMsg = allMessages[allMessages.length - 1];
    const maxId = store.roleMaxId ?? 0;
    saveCheckpoint(latestMsg?.message_id ?? 0, maxId);
  }

  console.info(`[roleScanner] 扫描完成: 处理 ${messagesToScan.length} 条消息`);
}

/**
 * 防抖调度扫描
 */
export function scheduleScan(mode: 'full' | 'incremental'): void {
  if (debounceTimer) clearTimeout(debounceTimer);
  debounceTimer = setTimeout(() => {
    performScan(mode);
    debounceTimer = null;
  }, CONFIG.debounceDelay);
}

/**
 * 手动触发全量扫描（供 UI 按钮调用）
 */
export function manualFullScan(): void {
  console.info('[roleScanner] 手动触发全量扫描');
  if (debounceTimer) { clearTimeout(debounceTimer); debounceTimer = null; }
  performScan('full');
}

// ============================================================================
// 初始化与事件绑定
// ============================================================================

/**
 * 初始化角色扫描器
 */
export function initRoleScanner(): void {
  if (typeof tavern_events === 'undefined') {
    console.warn('[roleScanner] tavern_events 未定义，跳过初始化');
    return;
  }

  // 新消息到来 → 增量扫描
  eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, () => scheduleScan('incremental'));

  // 删楼/回滚/修改楼层 → 全量扫描
  ([
    tavern_events.MESSAGE_DELETED,
    tavern_events.MESSAGE_SWIPED,
    tavern_events.MESSAGE_UPDATED,
  ] as const).forEach(e => {
    eventOn(e, () => {
      invalidateCheckpoint();
      scheduleScan('full');
    });
  });

  // 切换聊天 → 全量扫描
  eventOn(tavern_events.CHAT_CHANGED, () => {
    invalidateCheckpoint();
    scheduleScan('full');
  });

  // 生成开始 → 按检查点选择模式
  eventOn('generation_started', () => {
    const cp = loadCheckpoint();
    scheduleScan(cp ? 'incremental' : 'full');
  });

  // 初始化扫描
  const cp = loadCheckpoint();
  scheduleScan(cp ? 'incremental' : 'full');

  console.info('[roleScanner] 角色扫描器初始化完成');
}
